using System;using System.Collections.Generic;using Game.Components;using Unity.Entities;namespace Game.Runtime{
internal sealed class SourceCampPrefabBinding{internal readonly LogicalCatalogPrefab Logical;internal readonly SourceUnitPrefab Command;internal SourceCampPrefabBinding(LogicalCatalogPrefab logical,SourceUnitPrefab command){Logical=logical;Command=command;}}
internal sealed class SourceCampIdentityMap{
 readonly Dictionary<SourceUnitPrefab,LogicalCatalogPrefab> logical=new Dictionary<SourceUnitPrefab,LogicalCatalogPrefab>();readonly Dictionary<LogicalCatalogPrefab,SourceUnitPrefab> command=new Dictionary<LogicalCatalogPrefab,SourceUnitPrefab>();
 internal SourceCampIdentityMap(EntityManager em,CatalogPrefabStore store,IReadOnlyList<SourceCampPrefabBinding> sourceBindings,bool sourceBindingDomainComplete){if(!sourceBindingDomainComplete||sourceBindings==null)throw new NotSupportedException("Complete authored prefab-to-template identity mapping required");foreach(var x in sourceBindings){if(x?.Logical==null||x.Command==null||!em.Exists(x.Command.Template)||!string.Equals(x.Logical.name,x.Command.name,StringComparison.Ordinal)||logical.ContainsKey(x.Command)||command.ContainsKey(x.Logical))throw new NotSupportedException("Unique same-source prefab/template identity required, no name-only lookup");store.TryGetUnit(x.Logical,out _);logical.Add(x.Command,x.Logical);command.Add(x.Logical,x.Command);}}
 internal LogicalCatalogPrefab Logical(SourceUnitPrefab prefab){if(prefab==null)return null;if(!logical.TryGetValue(prefab,out var p))throw new NotSupportedException("Source command prefab outside closed logical identity map");return p;}internal SourceUnitPrefab Command(LogicalCatalogPrefab prefab){if(prefab==null)return null;if(!command.TryGetValue(prefab,out var p))throw new NotSupportedException("Logical prefab missing actual command/template identity");return p;}}
internal sealed class SourceCampReadScope:IDisposable{[ThreadStatic]internal static SourceCampReadScope Current;internal readonly EntityManager Em;internal readonly SourceCampIdentityMap Map;readonly CatalogMetadataReadScope catalog;
 internal SourceCampReadScope(EntityManager em,CatalogPrefabStore store,CatalogPublicFacts facts,SourceCampIdentityMap map){if(Current!=null||SourceS073LegacyCatalogScope.Current!=null)throw new NotSupportedException("Nested or cross-profile availability context unsupported");Em=em;Map=map;using var q=em.CreateEntityQuery(typeof(SkirmishExpandedSessionComponent),typeof(SkirmishProductionCatalogRecord));if(q.CalculateEntityCount()!=1)throw new NotSupportedException("One actual source session/catalog required");var owner=q.GetSingletonEntity();if(em.GetComponentData<SkirmishExpandedSessionComponent>(owner).Phase!=Game.Skirmish.Contracts.SkirmishSessionPhase.Playing)throw new NotSupportedException("Only Playing S002 source availability admitted");var record=em.GetComponentObject<SkirmishProductionCatalogRecord>(owner).Catalog;SourceGroundMissionFamily.RequireCatalogSetup(record?.Setup);catalog=new CatalogMetadataReadScope(em,store,facts,record);Current=this;}
 public void Dispose(){if(!ReferenceEquals(Current,this))throw new InvalidOperationException("Availability context ownership lost");Current=null;catalog.Dispose();}}
internal sealed class SourceS073LegacyCatalogScope:IDisposable{
 [ThreadStatic] internal static SourceS073LegacyCatalogScope Current;
 readonly EntityManager em;readonly HashSet<SourceUnitPrefab> configured;
 static readonly string[] Expected={"Unit_Chr_Soldier_Male_02_Alt_04","Unit_Veh_Truck_Tray","Unit_Veh_Truck_Tanker"};
 static readonly string[] ExpectedGuids={"ff73c8b7cbf844778916da330e9cd3e3","57f2dccc00faf49bca391aa1cc44d70a","e9015a8d3f0294ca6ac7bf8614ac2e7e"};
 static readonly long[] ExpectedLocalIds={3282182154612916099L,8579631638336695248L,8579631638336695248L};
 internal SourceS073LegacyCatalogScope(EntityManager manager,GeneratedUnitProductionMetadata metadata){
  if(Current!=null||SourceCampReadScope.Current!=null||manager==default||metadata==null||!metadata.FactoryDomainQualified||metadata.Ordered==null||metadata.Ordered.Count!=Expected.Length)throw new NotSupportedException("Fresh exact source-qualified S073 legacy unit registry required");
  using(var sessions=manager.CreateEntityQuery(typeof(SkirmishMatchState))){if(sessions.CalculateEntityCount()!=1)throw new NotSupportedException("Unique actual S073 match required");var match=sessions.GetSingleton<SkirmishMatchState>();if(match.ScenarioIndex!=3||match.Phase!=SkirmishPhase.Playing)throw new NotSupportedException("Only the admitted playing S073 legacy match is supported");}
  using(var expanded=manager.CreateEntityQuery(typeof(SkirmishExpandedSessionComponent)))if(expanded.CalculateEntityCount()!=0)throw new NotSupportedException("S073 legacy catalog cannot replace expanded-session policy");
  configured=new HashSet<SourceUnitPrefab>();for(int i=0;i<Expected.Length;i++){var row=metadata.Ordered[i];var prefab=row?.Prefab;if(row==null||row.Index!=i||prefab==null||prefab.name!=Expected[i]||(string)row.AssetIdentity?["guid"]!=ExpectedGuids[i]||(long?)row.AssetIdentity?["local_id"]!=ExpectedLocalIds[i]||!manager.Exists(prefab.Template)||!configured.Add(prefab))throw new NotSupportedException("Exact ordered original S073 configured prefab GUID/local-ID/template identities required");}
  em=manager;Current=this;
 }
 internal bool Allows(EntityManager manager,SourceUnitPrefab prefab,bool building){if(!ReferenceEquals(manager,em))throw new NotSupportedException("S073 catalog scope belongs to another world");return !building&&prefab!=null&&configured.Contains(prefab);}
 public void Dispose(){if(!ReferenceEquals(Current,this))throw new InvalidOperationException("S073 catalog scope ownership lost");Current=null;}
}
internal static class SourceCampCatalogPolicy{internal static bool Allows(EntityManager em,SourceUnitPrefab prefab,bool building){var legacy=SourceS073LegacyCatalogScope.Current;if(legacy!=null)return legacy.Allows(em,prefab,building);var c=SourceCampReadScope.Current;if(c==null||!ReferenceEquals(c.Em,em))throw new NotSupportedException("Exact retained availability world required");return SourceCatalogPolicy.Allows(em,c.Map.Logical(prefab),building);}}
internal static class SourceCampCatalogTokenAllows{internal static bool Allows(this SkirmishProductionCatalog catalog,SourceUnitPrefab prefab,bool building){var c=SourceCampReadScope.Current;if(c==null||!ReferenceEquals(catalog,CatalogMetadataReadScope.Current.Catalog))throw new NotSupportedException("Exact source catalog reference required");return SourceCampCatalogPolicy.Allows(c.Em,prefab,building);}}
